; title=&quot;Bain&quot;&gt;Bain (froid)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2 pc&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;bergement-Et-Services.html#Bain&quot; title=&quot;H&#233;bergement et services&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Bain-(Objet).html&quot; title=&quot;Bain&quot;&gt;Bain (public)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;2 pa–1 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;bergement-Et-Services.html#Compagnecompagnon&quot; title=&quot;H&#233;bergement et services&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Compagnecompagnon-(Objet).html&quot; title=&quot;Compagne/compagnon&quot;&gt;Compagne/compagnon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5 pc–10 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;bergement-Et-Services.html#Domestique&quot; title=&quot;H&#233;bergement et services&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Domestique-(Objet).html&quot; title=&quot;Domestique&quot;&gt;Domestique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;bergement-Et-Services.html#Employ&#233;&quot; title=&quot;H&#233;bergement et services&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Employ&#233;-(Objet).html&quot; title=&quot;Employ&#233;&quot;&gt;Employ&#233; (qualifi&#233;)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;3 pa/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;bergement-Et-Services.html#Employ&#233;&quot; title=&quot;H&#233;bergement et services&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Employ&#233;-(Objet).html&quot; title=&quot;Employ&#233;&quot;&gt;Employ&#233; (sans formation)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 pa/jour&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#2